import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z3 } from "npm:zod@^3.25.76";
var get_product_default = defineTool3({
  name: "get_product",
  title: "Get product",
  description: "Get full details for a single Tripplefour product by its ID.",
  inputSchema: {
    id: z3.string().min(1).describe("Product ID, e.g. 'vp-lz-cherry'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const p = catalog.find((x) => x.id === id);
    if (!p) {
      return {
        content: [{ type: "text", text: `No product found with id '${id}'.` }],
        isError: true
      };
    }
    const item = {
      id: p.id,
      name: p.name,
      category: p.category,
      price_zar: p.price,
      description: p.description,
      coming_soon: p.comingSoon ?? false,
      url: productUrl(p.id)
    };
    return {
      content: [{ type: "text", text: JSON.stringify(item, null, 2) }],
      structuredContent: item
    };
  }
});

